export type EntityId = (typeof COMPANY)['entities'][number]['id']

export function getEntity(id: string): Entity | undefined {
  return COMPANY.entities.find((e) => e.id === id)
}

export function entityAccounts(entity: Entity): Account[] {
  return entity.banks.flatMap((b) => b.accounts)
}

export function formatSGD(amount: number): string {
  return `S$ ${amount.toLocaleString('en-SG', {
    minimumFractionDigits: 2,
    maximumFractionDigits: 2,
  })}`
}

export type KpiCard = {
  label: string
  value: string
  delta: string
  sub: string
}

export type ActivityItem = {
  id: string
  text: string
  time: string
  actor: string
}

export function entityKpis(entity: Entity): KpiCard[] {
  const accounts = entityAccounts(entity)
  const total = accounts.reduce((sum, a) => sum + a.lastBalance, 0)
  const txns = ENTITY_TRANSACTIONS[entity.id] ?? []
  const txnsCount = txns.length
  const pendingFromRefunds = entity.id === 'ent_acme_labs_sg' ? unprocessedRefunds.length : 0
  const failedFromWithdrawals = entity.id === 'ent_acme_labs_sg'
    ? allPayments.filter((p) => p.status === 'FAILED').length
    : 0
  return [
    {
      label: 'Transactions today',
      value: String(txnsCount),
      delta: txnsCount > 0 ? '+' + txnsCount : '0',
      sub: 'across all rails',
    },
    {
      label: 'Balances total',
      value: formatSGD(total),
      delta: '+0.6%',
      sub: `across ${accounts.length} account${accounts.length === 1 ? '' : 's'}`,
    },
    {
      label: 'Pending approvals',
      value: String(pendingFromRefunds),
      delta: pendingFromRefunds > 0 ? `${pendingFromRefunds} new` : '0 new',
      sub: '',
    },
    {
      label: 'Failed payments',
      value: String(failedFromWithdrawals),
      delta: failedFromWithdrawals > 0 ? `+${failedFromWithdrawals}` : '0',
      sub: 'last 24h',
    },
  ]
}

