export type PaymentStatus = 'FAILED' | 'COMPLETED' | 'PENDING'

export type Payment = {
  id: string
  amount: string
  createdAt: string
  currency: string
  senderAccountId: string
  status: PaymentStatus
  type: string
  updatedAt: string
  organizationId: string
  mode: 'LIVE' | 'TEST'
  receiverBank: string
  receiverName: string
  receiverBankAccountNumber: string
  receiverLocalRoutingIdentifier: string
  resultCode: string
  underlyingErrorMessage: string
  customerReference: string
  paymentDetails: string
}

export function paymentRequiresAttention(p: Payment): boolean {
  if (p.status !== 'FAILED') return false
  return ['REJECTED_BY_SENDING_BANK', 'OTHERS'].includes(p.resultCode)
}

